-- Elimina informes duplicados (mismo jugador, partido, fecha y tipo de informe) dejando el más reciente.
-- Antes de borrar, copia al informe que queda los campos que solo tenía el duplicado.
update public.reports r set data = v.patch::jsonb || r.data from (values
('26624b72-a877-42ac-bd8c-949049553678','{"agente": "AT REPRESENTACIONES", "car_EXTREMO": "ASOCIATIVO: Es capaz de interiorizar, para enlazar pases que puedan permitir un juego por dentro.", "car_extremo": "ASOCIATIVO: Es capaz de interiorizar, para enlazar pases que puedan permitir un juego por dentro."}'),
('2f5948d0-3e6d-48a8-9eaa-5fe738cd08f8','{"agente": "PROYECTA PLAYERS"}'),
('367f44fb-b979-4374-b9e1-1a6d8d2ce772','{"observacion": "Central que busca constantemente el duelo físico, va con contundencia y algo de agresividad al marcaje, por momentos le falta mantener serenidad y concentración para sostener su rendimiento durante todo el partido, destaca por ser un defensor con buena proyección ofensiva, tanto para proyectar balones en largo con criterio, así también para causar peligro cuando sube a cabecear en pelotas quietas, no es espigado pero posee buen salto. Perfil para seguir observando pero sin ser prioridad en el mercado."}'),
('7aa65144-6068-4d71-9e1d-71701850457d','{"agente": "HERNAN BERMAN", "car_EXTREMO": "TALENTO: Gran manejo del balón en espacios reducidos. Mucha calidad técnica para el regate y la conducción en corto.", "car_extremo": "TALENTO: Gran manejo del balón en espacios reducidos. Mucha calidad técnica para el regate y la conducción en corto."}'),
('05dbd42f-d66c-468f-a7ce-6f10f72d9774','{"link1": "https://www.transfermarkt.es/franco-diaz/profil/spieler/748060", "obsercacion": "Muestra gran inteligencia y claridad para jugar, decide bien normalmente con el balón. Tiene buena técnica para mantener la posesión y evitar que le roben el balón. Buen biotipo y comprometido en ambas fases del juego, tiene gran despliegue", "car_INTERIOR": "RECORRIDO: Capaz de abarcar todo el frente de ataque. Subiendo y bajando constantemente para apoyar. Gran resistencia.", "car_interior": "RECORRIDO: Capaz de abarcar todo el frente de ataque. Subiendo y bajando constantemente para apoyar. Gran resistencia."}'),
('0a289358-af57-4a8f-90da-45a49f881445','{"agente_2": "Hernan Berman", "observacion_10": "Central de muy bueno juego de pies, sale bien antes presiones y busca filtrar pases en campo rival. Comete pocos errores con la pelota dominada e incluso se atreve a conducir o intentar avanzar con paredes ante bloques bajos. Tiene buena velocidad y es intuitivo al momento de marcar a campo abierto.", "rol_de_jugador": "TITULAR", "tipo_de_visualizacion": "VIDEO", "control_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "4", "ejecucion_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "4", "pase_corto_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "5", "pase_largo_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "3", "juego_aereo_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "4", "conducciones_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "4", "control_orientado_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "4", "cierres_1_muy_deficiente_2_deficiente_3_aceptable_4_bueno_5_muy_bueno_2": "4", "registros_pierna_habil_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "5", "anticipacion_1_muy_deficiente_2_deficiente_3_aceptable_4_bueno_5_muy_bueno_3": "4", "registros_pierna_no__habil_1_malo__2_regular__3_correcto__4_bien__5_muy_bien": "3", "inicio_de_juego_1_muy_deficiente_2_deficiente_3_aceptable_4_bueno_5_muy_bueno_2": "5", "duelos_defensivos_1_muy_deficiente_2_deficiente_3_aceptable_4_bueno_5_muy_bueno_2": "4", "comportamiento_abp_of_1_sin_importancia___2_baja_relevancia__3__normal__4__alta__5__muy_inmportante": "3", "comportamiento_abp_def_1_sin_importancia___2_baja_relevancia__3__normal__4__alta__5__muy_inmportante": "4", "busqueda_visual_1_no_escanea__2_escanea_poco__3_escanea_durante_algunas_aciones__4__casi_siempre_escanea_5__escanea_siempre": "4", "decisiones_con_balon_1___mayoria_de_malas__2___mas_malas_que_buenas__3_____buenas_y_malas__4____mas_buenas_que_malas__5__siempre_buenas": "4", "decisiones_sin_balon_1___mayoria_de_malas__2___mas_malas_que_buenas__3_____buenas_y_malas__4____mas_buenas_que_malas__5__siempre_buenas": "4"}'),
('03e366e0-0aab-4e7b-b88c-e4d29fa4625a','{"central": "INTUITIVO: Lee perfectamente las intenciones ofensivas. Gran intuición para anticiparse y prever jugadas de ataque. Gran capacidad técnica.", "observacion_2": "Central de muy buen manejo de pelota, filtró varios pases en campo rival. Tiene un buen pase diagonal para activar al lateral/extremo con trazos largos. Defensivamente se mostró fuerte en el duelo y siempre cercano al delantero, así como imponente por arriba. Muy interesante", "rol_de_jugador": "TITULAR", "tipo_de_visualizacion": "VIDEO", "link__tm__besoccer_o_algun_link_relevante_": "https://www.transfermarkt.es/patricio-pernicone/profil/spieler/856529"}'),
('169f9f20-413f-47f4-8b8c-b8ea36cc5db9','{"agente": "Delta Football"}'),
('2f5f41d3-3583-425c-8a68-a7d84351e4a2','{"link1": "https://www.transfermarkt.es/luis-canga/profil/spieler/189470", "agente": "Seth Sports"}'),
('bc09d9a8-0bef-4393-9678-0ef1dff5b88b','{"link1": "https://www.transfermarkt.es/agustin-gomez/profil/spieler/524311", "observacion": "Defensa central de muy buen juego aéreo, casi siempre bien perfilado y posicionado para cortar avances del rival con anticipos precisos, posee liderazgo comandando la línea de defensiva, tiene buena salida de balón en pase inicial, se maneja bien en ambos perfiles, no es demasiado rápido en aceleración o velocidad de punta, lo compensa muchas veces con colocación y lectura de juego, su paso por Ecuador fué destacado y viene jugando a buen nivel en su actual club, central comprobado en el fútbol ecuatoriano y perfil para tenerlo en consideración."}'),
('6048acfc-5bf6-4930-a705-337d6fcb6187','{"link2": "https://latam.analyticom.de/resources/jsf/person/index.xhtml?personType=Player&id=5283989"}'),
('00b79a57-68f8-4fdf-89ad-5cc38ff9952b','{"observacion": "Arquero ágil de reacción para recomponerse, pero da muchos rebotes y para su edad no es un arquero diferencial o que mejore al actual arquero del club. Descarte."}'),
('1532f72d-39db-4d54-8a99-2aad18c4ae4f','{"link2": "https://www.sofascore.com/es-la/football/player/mauro-luque/1066571", "agente": "GOAL IM"}'),
('60ccb773-f398-40d7-9070-b28a531628a9','{"link1": "https://es.besoccer.com/jugador/j-moran-851479", "agente": "SETH SPORTS", "link2": "https://www.sofascore.com/es-la/football/player/jordan-moran/1002519"}'),
('7e7d9db5-23b8-478b-a5fd-2ea3571fb9cd','{"link1": "https://www.transfermarkt.es/nicolas-monserrat/profil/spieler/873232", "link2": "https://www.sofascore.com/es-la/football/player/nicolas-monserrat/1108984", "agente": "LATIN PLAYERS"}'),
('8c50d44e-271b-4576-8eff-ca82197b60d4','{"observacion": "Es un arquero experimentado, tuvo paso por la selección de Ecuador, pero por edad y comparando con el arquero actual del club, no supera del todo o eleva el rendimiento, con todo no hay que descartarlo por cualquier cosa."}'),
('9dff1b47-c65a-490e-aeac-f4e463f41a1e','{"link1": "https://www.transfermarkt.es/thomas-amilivia/profil/spieler/639767", "link2": "https://www.sofascore.com/es-la/football/player/thomas-amilivia/966511", "agente": "LNBSOCCER", "observacion": "INGRESO A LA VARIANTE, INTENTA MOVERSE POR EL FRENTE DE ATAQUE, PERO NO INFLUYO EN EL PARTIDO"}'),
('c0c60394-ae20-4f95-bfdb-b9fe312471e7','{"link1": "https://www.transfermarkt.es/tobias-coppo/profil/spieler/689467", "agente": "FRONT GROUP GMBH", "observacion": "PRIMERA EXPERIENCIA EN EL EXTRANJERO, VIENE DEJANDO BUENAS SENSACIONES EN CANCHA"}'),
('ec3afb40-5faa-4728-97dc-de6f62b9a9f9','{"observacion": "Central de características físicas algo interesantes por su velocidad y juego aéreo, pero nada llamativo en líneas generales, hay mejores opciones en el mercado."}'),
('f0fa1abb-e2ec-4c8c-a3b6-0eea45f980ab','{"link1": "https://www.transfermarkt.es/leonel-nazareno/profil/spieler/298318", "link2": "https://www.sofascore.com/es-la/football/player/leonel-nazareno/805464", "agente": "SIN CONOCER", "observacion": "VIENE DESTACANDO A AÑO SEGUIDO, LA TEMPORADA ANTERIOR CON LIBERTAD Y LA ACTUAL CON LEONES."}'),
('57f257cd-3b48-4691-82c5-c9a61011c731','{"link1": "https://www.transfermarkt.es/braian-ramirez/profil/spieler/891682", "altura": "178 CM", "observacion": "Mediocentro que va intenso a los duelos defensivos, tiene un toque de agresividad en la disputa de balón, también posee bastante dinámica en toda la mitad de cancha y su personalidad es bastante destacada, mostrando carácter competitivo."}'),
('5c1995f6-76d6-4b81-80f2-8b60e0636117','{"car_MEDIAPUNTA": "LLEGADOR: Llega desde segunda línea para rematar al borde o dentro del área. Aparece sorpresivamente en el área rival.", "car_mediapunta": "LLEGADOR: Llega desde segunda línea para rematar al borde o dentro del área. Aparece sorpresivamente en el área rival."}'),
